export type UploadDocumentResponse = {
  document_id: string;
  correlation_id: string;
};

export class UploadApiError extends Error {
  readonly status: number;
  readonly payload?: unknown;

  constructor(status: number, message: string, payload?: unknown) {
    super(message);
    this.name = "UploadApiError";
    this.status = status;
    this.payload = payload;
  }
}

export type FetchLike = (
  input: RequestInfo | URL,
  init?: RequestInit
) => Promise<Response>;

export interface DocumentsUploadClient {
  upload(file: File): Promise<UploadDocumentResponse>;
}

export interface DocumentsUploadClientOptions {
  baseUrl: string;
  fetchImpl?: FetchLike;
}

function joinUrl(baseUrl: string, path: string): string {
  const normalizedBase = baseUrl.trim().endsWith("/")
    ? baseUrl.trim().slice(0, -1)
    : baseUrl.trim();

  return `${normalizedBase}${path}`;
}

async function readErrorPayload(response: Response): Promise<unknown> {
  const contentType = response.headers.get("content-type") ?? "";

  if (contentType.includes("application/json")) {
    try {
      return await response.json();
    } catch {
      return undefined;
    }
  }

  try {
    return await response.text();
  } catch {
    return undefined;
  }
}

function errorMessageFromPayload(status: number, payload: unknown): string {
  if (typeof payload === "string" && payload.trim().length > 0) {
    return payload;
  }

  if (payload && typeof payload === "object") {
    const maybePayload = payload as {
      message?: unknown;
      detail?: unknown;
      error?: unknown;
    };

    if (typeof maybePayload.message === "string" && maybePayload.message.trim()) {
      return maybePayload.message;
    }

    if (typeof maybePayload.detail === "string" && maybePayload.detail.trim()) {
      return maybePayload.detail;
    }

    if (typeof maybePayload.error === "string" && maybePayload.error.trim()) {
      return maybePayload.error;
    }
  }

  if (status === 401) {
    return "Sessione non valida. Reindirizzamento al login.";
  }

  if (status === 403) {
    return "Accesso non autorizzato.";
  }

  if (status === 0) {
    return "Servizio di caricamento non raggiungibile. Verificare la connessione e riprovare.";
  }

  return "Caricamento non riuscito. Riprovare.";
}

export function createDocumentsUploadClient(
  options: DocumentsUploadClientOptions
): DocumentsUploadClient {
  const fetchImpl = options.fetchImpl ?? fetch;

  return {
    async upload(file: File): Promise<UploadDocumentResponse> {
      const formData = new FormData();
      formData.append("file", file);

      let response: Response;

      try {
        response = await fetchImpl(joinUrl(options.baseUrl, "/documents"), {
          method: "POST",
          body: formData,
          headers: {
            Accept: "application/json"
          }
        });
      } catch (error) {
        throw new UploadApiError(
          0,
          errorMessageFromPayload(0, undefined),
          error
        );
      }

      if (!response.ok) {
        const payload = await readErrorPayload(response);
        throw new UploadApiError(
          response.status,
          errorMessageFromPayload(response.status, payload),
          payload
        );
      }

      const data = (await response.json()) as Partial<UploadDocumentResponse>;

      if (
        typeof data.document_id !== "string" ||
        typeof data.correlation_id !== "string"
      ) {
        throw new UploadApiError(
          502,
          "Risposta upload non valida dal backend.",
          data
        );
      }

      return {
        document_id: data.document_id,
        correlation_id: data.correlation_id
      };
    }
  };
}
