export type RuntimeProfile = "local" | "aws";

export interface UploadRuntimeConfig {
  runtimeProfile: RuntimeProfile;
  apiBaseUrl: string;
  loginUrl: string;
  unauthorizedUrl: string;
  nextActionBasePath: string;
}

export interface AuthNavigator {
  toLogin(): void;
  toUnauthorized(): void;
}

function readPublicEnv(name: string, fallback: string): string {
  const value = process.env[name];

  if (typeof value !== "string") {
    return fallback;
  }

  const normalized = value.trim();
  return normalized.length > 0 ? normalized : fallback;
}

function resolveRuntimeProfile(value: string): RuntimeProfile {
  return value === "aws" ? "aws" : "local";
}

export function defaultUploadRuntimeConfig(): UploadRuntimeConfig {
  return {
    runtimeProfile: resolveRuntimeProfile(
      readPublicEnv("NEXT_PUBLIC_RUNTIME_PROFILE", "local")
    ),
    apiBaseUrl: readPublicEnv(
      "NEXT_PUBLIC_API_BASE_URL",
      "http://127.0.0.1:8000"
    ),
    loginUrl: readPublicEnv(
      "NEXT_PUBLIC_LOGIN_URL",
      "http://127.0.0.1:8000/auth/login"
    ),
    unauthorizedUrl: readPublicEnv(
      "NEXT_PUBLIC_UNAUTHORIZED_URL",
      "/unauthorized"
    ),
    nextActionBasePath: readPublicEnv(
      "NEXT_PUBLIC_NEXT_ACTION_BASE_PATH",
      "/workflow/inbox?document_id="
    )
  };
}

export function buildNextActionHref(
  config: Pick<UploadRuntimeConfig, "nextActionBasePath">,
  documentId: string
): string {
  return `${config.nextActionBasePath}${encodeURIComponent(documentId)}`;
}

export function createWindowAuthNavigator(
  config: UploadRuntimeConfig,
  locationRef?: Pick<Location, "assign">
): AuthNavigator {
  const resolvedLocation =
    locationRef ??
    (typeof window !== "undefined" ? window.location : undefined);

  return {
    toLogin(): void {
      resolvedLocation?.assign(config.loginUrl);
    },
    toUnauthorized(): void {
      resolvedLocation?.assign(config.unauthorizedUrl);
    }
  };
}
