import type { ChangeEvent, DragEvent } from "react";

export interface FileDropzoneProps {
  selectedFileName?: string;
  error?: string | null;
  disabled?: boolean;
  accept?: string;
  onFileSelected(file: File | null): void;
}

export function FileDropzone({
  selectedFileName,
  error,
  disabled = false,
  accept = ".pdf,.docx,.jpg,.jpeg,.png",
  onFileSelected
}: FileDropzoneProps) {
  function handleInputChange(event: ChangeEvent<HTMLInputElement>) {
    if (disabled) {
      return;
    }

    const file = event.target.files?.[0] ?? null;
    onFileSelected(file);
  }

  function handleDragOver(event: DragEvent<HTMLDivElement>) {
    event.preventDefault();
  }

  function handleDrop(event: DragEvent<HTMLDivElement>) {
    event.preventDefault();

    if (disabled) {
      return;
    }

    const file = event.dataTransfer.files?.[0] ?? null;
    onFileSelected(file);
  }

  return (
    <section
      aria-label="Area di caricamento documento"
      className="rounded-lg border border-dashed border-slate-400 bg-slate-50 p-6"
    >
      <div
        data-testid="upload-dropzone"
        aria-disabled={disabled}
        onDragOver={handleDragOver}
        onDrop={handleDrop}
        className="rounded-md border border-slate-300 bg-white p-8 text-center"
      >
        <p className="text-lg font-semibold text-slate-900">
          Trascina qui il documento
        </p>
        <p
          id="upload-supported-formats"
          className="mt-2 text-sm text-slate-600"
        >
          Formati supportati: PDF, DOCX, JPG, PNG — massimo 20 MB
        </p>
      </div>

      <div className="mt-4">
        <label
          htmlFor="document-upload-input"
          className="block text-sm font-medium"
        >
          Seleziona file
        </label>
        <input
          id="document-upload-input"
          name="file"
          aria-label="Seleziona file"
          aria-describedby="upload-supported-formats"
          type="file"
          accept={accept}
          disabled={disabled}
          onChange={handleInputChange}
          className="mt-2 block w-full rounded border border-slate-300 p-2 text-sm"
        />
      </div>

      <div className="mt-3 min-h-6 text-sm text-slate-700" aria-live="polite">
        {selectedFileName
          ? `File selezionato: ${selectedFileName}`
          : "Nessun file selezionato."}
      </div>

      {error ? (
        <div
          role="alert"
          className="mt-3 rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
        >
          {error}
        </div>
      ) : null}
    </section>
  );
}
