"use client";

import { useMemo, useState, type FormEvent } from "react";

import {
  createDocumentsUploadClient,
  type DocumentsUploadClient
} from "../../shared/api/documentsUpload";
import { UploadApiError } from "../../shared/api/documentsUpload";
import {
  buildNextActionHref,
  createWindowAuthNavigator,
  defaultUploadRuntimeConfig,
  type AuthNavigator,
  type UploadRuntimeConfig
} from "../../shared/auth/runtime";
import { FileDropzone } from "../../shared/ui/FileDropzone";
import { useUploadDocument } from "./useUploadDocument";

const MAX_FILE_SIZE_BYTES = 20 * 1024 * 1024;

const SUPPORTED_UPLOAD_TYPES = [
  {
    extension: "pdf",
    mimeTypes: ["application/pdf"]
  },
  {
    extension: "docx",
    mimeTypes: [
      "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
    ]
  },
  {
    extension: "jpg",
    mimeTypes: ["image/jpeg"]
  },
  {
    extension: "jpeg",
    mimeTypes: ["image/jpeg"]
  },
  {
    extension: "png",
    mimeTypes: ["image/png"]
  }
] as const;

function getFileExtension(fileName: string): string {
  const parts = fileName.toLowerCase().split(".");
  return parts.length > 1 ? parts[parts.length - 1] : "";
}

function findSupportedTypeByExtension(extension: string) {
  return SUPPORTED_UPLOAD_TYPES.find((type) => type.extension === extension);
}

function isSupportedMimeType(mimeType: string): boolean {
  return SUPPORTED_UPLOAD_TYPES.some((type) =>
    type.mimeTypes.includes(mimeType)
  );
}

export function validateUploadCandidate(file: File | null): string | null {
  if (!file) {
    return "Seleziona un file da caricare.";
  }

  if (file.size > MAX_FILE_SIZE_BYTES) {
    return "File troppo grande. Il limite massimo è 20 MB.";
  }

  const extension = getFileExtension(file.name);
  const supportedType = findSupportedTypeByExtension(extension);

  if (!supportedType) {
    return "Formato non supportato. Carica un file PDF, DOCX, JPG o PNG.";
  }

  const mimeType = file.type.trim().toLowerCase();

  if (mimeType.length === 0) {
    return null;
  }

  if (!isSupportedMimeType(mimeType)) {
    return "Formato non supportato. Carica un file PDF, DOCX, JPG o PNG.";
  }

  if (!supportedType.mimeTypes.includes(mimeType)) {
    return "Il tipo del file non corrisponde all'estensione selezionata.";
  }

  return null;
}

export interface UploadPageProps {
  client?: DocumentsUploadClient;
  authNavigator?: AuthNavigator;
  runtimeConfig?: UploadRuntimeConfig;
}

export function UploadPage({
  client,
  authNavigator,
  runtimeConfig
}: UploadPageProps) {
  const resolvedRuntimeConfig = useMemo(
    () => runtimeConfig ?? defaultUploadRuntimeConfig(),
    [runtimeConfig]
  );

  const resolvedClient = useMemo(
    () =>
      client ??
      createDocumentsUploadClient({
        baseUrl: resolvedRuntimeConfig.apiBaseUrl
      }),
    [client, resolvedRuntimeConfig.apiBaseUrl]
  );

  const resolvedAuthNavigator = useMemo(
    () => authNavigator ?? createWindowAuthNavigator(resolvedRuntimeConfig),
    [authNavigator, resolvedRuntimeConfig]
  );

  const uploadMutation = useUploadDocument({
    client: resolvedClient,
    authNavigator: resolvedAuthNavigator
  });

  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [validationError, setValidationError] = useState<string | null>(null);

  function handleFileSelected(file: File | null) {
    setSelectedFile(file);
    setValidationError(file ? validateUploadCandidate(file) : null);
    uploadMutation.reset();
  }

  function handleSubmit(event?: FormEvent<HTMLFormElement>) {
    event?.preventDefault();

    const error = validateUploadCandidate(selectedFile);
    setValidationError(error);

    if (error || !selectedFile) {
      return;
    }

    uploadMutation.mutate(selectedFile);
  }

  const redirectMessage =
    uploadMutation.error instanceof UploadApiError &&
    uploadMutation.error.status === 401
      ? "Reindirizzamento al login in corso..."
      : uploadMutation.error instanceof UploadApiError &&
          uploadMutation.error.status === 403
        ? "Reindirizzamento alla pagina non autorizzata in corso..."
        : null;

  const nextActionHref = uploadMutation.data
    ? buildNextActionHref(
        resolvedRuntimeConfig,
        uploadMutation.data.document_id
      )
    : null;

  const isSubmitDisabled =
    uploadMutation.isPending || !selectedFile || validationError !== null;

  return (
    <main className="mx-auto max-w-5xl p-6 lg:grid lg:grid-cols-[2fr_1fr] lg:gap-8">
      <section>
        <header className="mb-6">
          <p className="text-sm font-medium uppercase tracking-wide text-slate-500">
            Caricamento documenti
          </p>
          <h1 className="mt-2 text-3xl font-bold text-slate-950">
            Carica un documento
          </h1>
          <p className="mt-2 text-sm text-slate-600">
            Il file viene inviato alla pipeline documentale. Sono accettati PDF,
            DOCX, JPG e PNG fino a 20 MB.
          </p>
        </header>

        <form onSubmit={handleSubmit} noValidate>
          <FileDropzone
            selectedFileName={selectedFile?.name}
            error={validationError}
            disabled={uploadMutation.isPending}
            onFileSelected={handleFileSelected}
          />

          <div className="mt-4 flex items-center gap-3">
            <button
              type="submit"
              disabled={isSubmitDisabled}
              className="rounded bg-slate-900 px-4 py-2 text-sm font-semibold text-white disabled:opacity-60"
            >
              {uploadMutation.isPending
                ? "Caricamento in corso..."
                : "Avvia caricamento"}
            </button>
            <span className="text-xs text-slate-500">
              Il caricamento è consentito solo per file validi.
            </span>
          </div>
        </form>

        {uploadMutation.isPending ? (
          <div
            role="status"
            aria-live="polite"
            className="mt-4 rounded border border-slate-300 bg-slate-50 p-3 text-sm text-slate-700"
          >
            Upload in corso. Attendere la conferma del backend.
          </div>
        ) : null}

        {redirectMessage ? (
          <div
            role="status"
            aria-live="polite"
            className="mt-4 rounded border border-amber-300 bg-amber-50 p-3 text-sm text-amber-800"
          >
            {redirectMessage}
          </div>
        ) : null}

        {uploadMutation.isError && !redirectMessage ? (
          <div
            role="alert"
            className="mt-4 rounded border border-red-300 bg-red-50 p-3 text-sm text-red-700"
          >
            {uploadMutation.error.message}
          </div>
        ) : null}

        {uploadMutation.isSuccess ? (
          <section className="mt-6 rounded border border-emerald-300 bg-emerald-50 p-4">
            <h2 className="text-base font-semibold text-emerald-900">
              Upload completato
            </h2>
            <p className="mt-2 text-sm text-emerald-800">
              document_id: <code>{uploadMutation.data.document_id}</code>
            </p>
            <p className="mt-1 text-sm text-emerald-800">
              correlation_id: <code>{uploadMutation.data.correlation_id}</code>
            </p>
            {nextActionHref ? (
              <a
                href={nextActionHref}
                className="mt-3 inline-block text-sm font-semibold text-emerald-900 underline"
              >
                Vai alla prossima azione
              </a>
            ) : null}
          </section>
        ) : null}
      </section>

      <aside className="mt-8 rounded-lg border border-slate-200 bg-white p-5 lg:mt-0">
        <h2 className="text-lg font-semibold text-slate-900">
          Cosa succede dopo
        </h2>
        <ol className="mt-3 list-decimal space-y-2 pl-5 text-sm text-slate-700">
          <li>Il backend registra il documento nello stato iniziale.</li>
          <li>La pipeline asincrona avvia parsing, OCR e classificazione.</li>
          <li>L’operatore prosegue dalla inbox o dalla schermata successiva.</li>
        </ol>
        <p className="mt-4 text-xs text-slate-500">
          Profilo runtime attivo:{" "}
          <strong>{resolvedRuntimeConfig.runtimeProfile}</strong>
        </p>
      </aside>
    </main>
  );
}
