import React from "react";
import {
  cleanup,
  fireEvent,
  render,
  screen,
  waitFor
} from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { afterEach, describe, expect, it, vi } from "vitest";

import Page from "../../../src/node/frontend/app/intake/upload/page";
import {
  UploadPage,
  validateUploadCandidate
} from "../../../src/node/frontend/app/intake/upload/UploadPage";
import { UploadApiError } from "../../../src/node/frontend/app/shared/api/documentsUpload";
import {
  createWindowAuthNavigator,
  type AuthNavigator,
  type UploadRuntimeConfig
} from "../../../src/node/frontend/app/shared/auth/runtime";

function createQueryClient() {
  return new QueryClient({
    defaultOptions: {
      queries: {
        retry: false
      },
      mutations: {
        retry: false
      }
    }
  });
}

function renderWithProviders(ui: React.ReactElement) {
  const queryClient = createQueryClient();

  return render(
    <QueryClientProvider client={queryClient}>{ui}</QueryClientProvider>
  );
}

function createFile(name: string, type: string, sizeBytes: number): File {
  return new File([new Uint8Array(sizeBytes)], name, { type });
}

function createJsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json"
    }
  });
}

function makeNavigator(): AuthNavigator & {
  toLogin: ReturnType<typeof vi.fn>;
  toUnauthorized: ReturnType<typeof vi.fn>;
} {
  return {
    toLogin: vi.fn(),
    toUnauthorized: vi.fn()
  };
}

function makeRuntimeConfig(): UploadRuntimeConfig {
  return {
    runtimeProfile: "local",
    apiBaseUrl: "http://127.0.0.1:8000",
    loginUrl: "http://127.0.0.1:8000/auth/login",
    unauthorizedUrl: "/unauthorized",
    nextActionBasePath: "/workflow/inbox?document_id="
  };
}

function setPublicRuntimeEnv(overrides?: Partial<Record<string, string>>) {
  process.env.NEXT_PUBLIC_RUNTIME_PROFILE =
    overrides?.NEXT_PUBLIC_RUNTIME_PROFILE ?? "local";
  process.env.NEXT_PUBLIC_API_BASE_URL =
    overrides?.NEXT_PUBLIC_API_BASE_URL ?? "http://127.0.0.1:8000";
  process.env.NEXT_PUBLIC_LOGIN_URL =
    overrides?.NEXT_PUBLIC_LOGIN_URL ?? "http://127.0.0.1:8000/auth/login";
  process.env.NEXT_PUBLIC_UNAUTHORIZED_URL =
    overrides?.NEXT_PUBLIC_UNAUTHORIZED_URL ?? "/unauthorized";
  process.env.NEXT_PUBLIC_NEXT_ACTION_BASE_PATH =
    overrides?.NEXT_PUBLIC_NEXT_ACTION_BASE_PATH ??
    "/workflow/inbox?document_id=";
}

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
});

describe("REQ-004 UploadPage", () => {
  it("accepts supported extensions even when the browser omits the MIME type", () => {
    const docxFile = createFile("documento.docx", "", 1024);

    expect(validateUploadCandidate(docxFile)).toBeNull();
  });

  it("blocks mismatched extension and MIME combinations before submission", () => {
    const fakePdf = createFile("fattura.pdf", "image/png", 1024);

    expect(validateUploadCandidate(fakePdf)).toContain("non corrisponde");
  });

  it("shows document_id and next action link after a valid upload using drag and drop", async () => {
    const upload = vi.fn().mockResolvedValue({
      document_id: "c0f5efb7-1e27-4c15-ae42-e4d983fd45b2",
      correlation_id: "corr-123"
    });

    renderWithProviders(
      <UploadPage
        client={{ upload }}
        authNavigator={makeNavigator()}
        runtimeConfig={makeRuntimeConfig()}
      />
    );

    const pdfFile = createFile("fattura.pdf", "application/pdf", 1024);

    fireEvent.drop(screen.getByTestId("upload-dropzone"), {
      dataTransfer: {
        files: [pdfFile]
      }
    });

    expect(screen.getByText(/File selezionato: fattura\.pdf/i)).toBeTruthy();

    fireEvent.click(
      screen.getByRole("button", { name: /avvia caricamento/i })
    );

    await waitFor(() => {
      expect(upload).toHaveBeenCalledTimes(1);
    });

    expect(screen.getByText(/Upload completato/i)).toBeTruthy();
    expect(screen.getByText(/document_id:/i).textContent).toContain(
      "c0f5efb7-1e27-4c15-ae42-e4d983fd45b2"
    );
    expect(
      screen.getByRole("link", { name: /vai alla prossima azione/i })
    ).toHaveProperty(
      "href",
      "http://localhost:3000/workflow/inbox?document_id=c0f5efb7-1e27-4c15-ae42-e4d983fd45b2"
    );
  });

  it("uploads from the route entrypoint with the file picker and shared fetch client", async () => {
    setPublicRuntimeEnv();

    const fetchMock = vi.fn().mockResolvedValue(
      createJsonResponse(200, {
        document_id: "c0f5efb7-1e27-4c15-ae42-e4d983fd45b2",
        correlation_id: "corr-456"
      })
    );

    vi.stubGlobal("fetch", fetchMock);

    renderWithProviders(<Page />);

    const input = screen.getByLabelText(/seleziona file/i);
    const validFile = createFile("contratto.pdf", "application/pdf", 1024);

    fireEvent.change(input, {
      target: {
        files: [validFile]
      }
    });

    const button = screen.getByRole("button", { name: /avvia caricamento/i });
    expect((button as HTMLButtonElement).disabled).toBe(false);

    fireEvent.click(button);

    await screen.findByText(/Upload completato/i);

    expect(fetchMock).toHaveBeenCalledTimes(1);
    expect(fetchMock.mock.calls[0]?.[0]).toBe("http://127.0.0.1:8000/documents");

    const requestInit = fetchMock.mock.calls[0]?.[1] as RequestInit;
    expect(requestInit.method).toBe("POST");
    expect(requestInit.body instanceof FormData).toBe(true);
    expect((requestInit.body as FormData).get("file")).toBe(validFile);

    expect(
      screen.getByRole("link", { name: /vai alla prossima azione/i })
    ).toHaveProperty(
      "href",
      "http://localhost:3000/workflow/inbox?document_id=c0f5efb7-1e27-4c15-ae42-e4d983fd45b2"
    );
  });

  it("blocks unsupported files from the route entrypoint before any network call", () => {
    setPublicRuntimeEnv();

    const fetchMock = vi.fn();
    vi.stubGlobal("fetch", fetchMock);

    renderWithProviders(<Page />);

    const input = screen.getByLabelText(/seleziona file/i);
    const invalidFile = createFile("script.exe", "application/octet-stream", 64);

    fireEvent.change(input, {
      target: {
        files: [invalidFile]
      }
    });

    const button = screen.getByRole("button", { name: /avvia caricamento/i });

    expect((button as HTMLButtonElement).disabled).toBe(true);
    expect(screen.getByRole("alert").textContent).toContain(
      "Formato non supportato"
    );
    expect(fetchMock).not.toHaveBeenCalled();
  });

  it("blocks files larger than 20 MB before submission", () => {
    const upload = vi.fn();

    renderWithProviders(
      <UploadPage
        client={{ upload }}
        authNavigator={makeNavigator()}
        runtimeConfig={makeRuntimeConfig()}
      />
    );

    const input = screen.getByLabelText(/seleziona file/i);
    const oversizedFile = createFile(
      "scan.png",
      "image/png",
      20 * 1024 * 1024 + 1
    );

    fireEvent.change(input, {
      target: {
        files: [oversizedFile]
      }
    });

    const button = screen.getByRole("button", { name: /avvia caricamento/i });

    expect((button as HTMLButtonElement).disabled).toBe(true);
